-- V58: Doi mac dinh quyen chi tiet (V57) - thay vi cap theo Role (WAREHOUSE_MANAGER du, SALES_STAFF
-- chi Xem+Tao), moi user KHONG phai ADMIN deu duoc cap toan bo quyen cua 6 nhom nghiep vu (Ban
-- hang/Giao hang/Hoa don/Tra hang/Kho/Danh muc) ngay tu dau, TRU rieng nhom "He thong" (van cua
-- ADMIN tu truoc gio - quan ly tai khoan/phan quyen nguoi khac) - nguoi quan tri sau do tu bo tich
-- tung dong rieng muon an/cam cho tung nguoi cu the. Don gian hoa theo yeu cau nguoi dung, khong
-- sua de V57 da chay (Flyway khong cho sua migration da ap dung).

UPDATE user u JOIN role r ON r.id = u.role_id SET u.permissions =
'sales_order:view,sales_order:create,sales_order:edit,sales_order:confirm,sales_order:cancel,sales_order:delete,sales_request:view,sales_request:create,sales_request:edit,sales_request:confirm,sales_request:delete,delivery_order:view,delivery_order:create,delivery_order:edit,delivery_order:confirm,delivery_order:cancel,delivery_order:delete,invoice:view,invoice:create,invoice:cancel,sales_return:view,sales_return:create,sales_return:edit,sales_return:confirm,sales_return:cancel,sales_return:delete,purchase_return:view,purchase_return:create,purchase_return:edit,purchase_return:confirm,purchase_return:delete,goods_receipt:view,goods_receipt:create,goods_receipt:edit,goods_receipt:confirm,goods_receipt:delete,goods_issue:view,goods_issue:create,goods_issue:edit,goods_issue:confirm,goods_issue:delete,inventory_transfer:view,inventory_transfer:create,inventory_transfer:edit,inventory_transfer:confirm_send,inventory_transfer:confirm_receive,inventory_transfer:delete,stock_take:view,stock_take:create,stock_take:edit,stock_take:confirm,stock_take:delete,stock_receipt:view,stock_receipt:create,stock_receipt:edit,stock_receipt:confirm,stock_receipt:delete,stock:view,product:view,product:create,product:edit,product:delete,product_category:view,product_category:create,product_category:edit,product_category:delete,product_group:view,product_group:create,product_group:edit,product_group:delete,customer:view,customer:create,customer:edit,customer:delete,customer_group:view,customer_group:create,customer_group:edit,customer_group:delete,customer_channel:view,customer_channel:create,customer_channel:edit,customer_channel:delete,supplier:view,supplier:create,supplier:edit,supplier:delete,warehouse:view,warehouse:create,warehouse:edit,warehouse:delete,branch:view,branch:create,branch:edit,branch:delete,selling_zone:view,selling_zone:create,selling_zone:edit,selling_zone:delete,route_master:view,route_master:create,route_master:edit,route_master:delete,region:view,region:create,region:edit,region:delete,province:view,province:create,province:edit,province:delete,district:view,district:create,district:edit,district:delete,ward:view,ward:create,ward:edit,ward:delete,uom:view,uom:create,uom:edit,uom:delete,uom_group:view,uom_group:create,uom_group:edit,uom_group:delete,tax_group:view,tax_group:create,tax_group:edit,tax_group:delete,price_list:view,price_list:create,price_list:edit,price_list:delete,employee:view,employee:create,employee:edit,employee:delete,employee_position:view,employee_position:create,employee_position:edit,employee_position:delete,salesman_type:view,salesman_type:create,salesman_type:edit,salesman_type:delete,company:view,company:edit'
WHERE r.code <> 'ADMIN';
